bool IsDangerousDownload(const DownloadItem& download, const FilePath& suggested_path, bool visited_referrer_before) {
    // Check if it's an extension without approval
    if (download.type == EXTENSION && !download.is_approved) {
        // Check if off-store extension installations are enabled
        if (!AreOffStoreExtensionsEnabled()) {
            return true;
        }
    }

    // Check if the file should be opened based on user gestures
    if (!download.initiated_by_user) {
        return true;
    }

    // Check danger level of the file
    if (download.danger_level == DANGEROUS) {
        return true;
    }

    // If referrer has not been visited, consider it dangerous
    if (!visited_referrer_before) {
        return true;
    }

    return false;
}

bool IsDownloadDangerous(const DownloadItem& download, const FilePath& suggested_path, bool visited_referrer_before) {
    // Check if off-store extension installations are enabled and if the download
    // is an extension without approval.
    bool is_offstore_install_allowed = IsOffStoreExtensionInstallAllowed(download);
    bool is_unapproved_extension = !IsExtensionApproved(download);

    // Check if the file should be opened based on user gestures.
    bool is_user_initiated = IsUserGesture(download);

    // Determine the danger level of the file.
    DangerLevel danger_level = GetFileDangerLevel(suggested_path, download);

    // Final determination based on the criteria.
    if ((is_unapproved_extension && !is_offstore_install_allowed) ||
        (danger_level == DANGEROUS && !is_user_initiated) ||
        (danger_level == VERY_DANGEROUS) ||
        (!visited_referrer_before && danger_level == DANGEROUS)) {
        return true;
    }

    return false;
}
